#!/usr/bin/env bash
set -euo pipefail

# Agricore: complete the Flutterwave -> IntaSend migration for COLLECTION + go-live host.
#  - utils/payments.py -> full drop-in (service_fee, create_payment_link[URL],
#    verify_transaction, verify_transfer, ...) with LIVE host payment.intasend.com
#  - utils/flutterwave.py shim -> re-export the full surface
#  - escrow/api/views.py -> FlutterwaveWebhookView swapped to IntaSend (challenge)
#  - settings.py + .env -> INTASEND_WEBHOOK_CHALLENGE
# Idempotent, dev-branch only, backs up + restores on failure. No migration.

PAY="utils/payments.py"; FW="utils/flutterwave.py"; VIEWS="escrow/api/views.py"

BR="$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo '')"
if [ -n "$BR" ] && [ "$BR" != "dev" ]; then echo ">> Refusing: branch '$BR' != 'dev'."; exit 1; fi
for f in "$PAY" "$FW" "$VIEWS"; do
  [ -f "$f" ] || { echo ">> Not found: $f  (run from Django root; run apply_intasend.sh first)"; exit 1; }
done
SETTINGS="$(grep -rl 'INSTALLED_APPS' --include=settings.py . 2>/dev/null | grep -v '_backup_' | head -1 || true)"
[ -n "$SETTINGS" ] || SETTINGS="agricore_project/settings.py"
[ -f "$SETTINGS" ] || { echo ">> Not found: settings.py"; exit 1; }
echo ">> settings.py: $SETTINGS"

TS="$(date +%Y%m%d-%H%M%S)"; BK="intasend_collect_backup_${TS}"
mkdir -p "$BK/utils" "$BK/escrow/api"
cp -a "$PAY" "$BK/utils/payments.py"; cp -a "$FW" "$BK/utils/flutterwave.py"
cp -a "$VIEWS" "$BK/escrow/api/views.py"; cp -a "$SETTINGS" "$BK/settings.py"
[ -f .env ] && cp -a .env "$BK/.env" || true
echo ">> Backup: $BK/"

set +e
python3 - "$PAY" "$FW" "$VIEWS" "$SETTINGS" <<'PYEOF'
import sys, ast, base64
PAY, FW, VIEWS, SETTINGS = sys.argv[1:5]
payments = base64.b64decode("").decode("utf-8")
shim     = base64.b64decode("").decode("utf-8")
newhook  = base64.b64decode("").decode("utf-8")
setblk   = base64.b64decode("IyAtLS0gQWdyaWNvcmUgSW50YVNlbmQgd2ViaG9vayAoaWRlbXBvdGVudCkgLS0tCklOVEFTRU5EX1dFQkhPT0tfQ0hBTExFTkdFID0gb3MuZW52aXJvbi5nZXQoIklOVEFTRU5EX1dFQkhPT0tfQ0hBTExFTkdFIiwgIiIpCg==").decode("utf-8")

cur = open(PAY, encoding="utf-8").read()
if "adapter-revision: 2" in cur and "payment.intasend.com" in cur:
    print("   payments.py already v2 (live host), skip")
else:
    ast.parse(payments); open(PAY,"w",encoding="utf-8").write(payments)
    print("   OK payments.py -> complete drop-in, live host payment.intasend.com")

cur = open(FW, encoding="utf-8").read()
if "verify_transaction" in cur:
    print("   flutterwave.py shim already complete, skip")
else:
    ast.parse(shim); open(FW,"w",encoding="utf-8").write(shim)
    print("   OK flutterwave.py shim widened")

src = open(VIEWS, encoding="utf-8").read()
if "IntaSend webhook (challenge-verified)" in src:
    print("   views.py webhook already IntaSend, skip")
else:
    start="class FlutterwaveWebhookView(APIView):"; end="\nclass PayoutAccountViewSet"
    i=src.find(start); j=src.find(end,i)
    if i<0 or j<0:
        print("   ERROR views.py: webhook anchors not found; aborting"); sys.exit(4)
    new_src=src[:i]+newhook.strip("\n")+"\n\n\n"+src[j+1:]
    try: ast.parse(new_src)
    except SyntaxError as e:
        print("   ERROR views.py would not parse: %s"%e); sys.exit(3)
    open(VIEWS,"w",encoding="utf-8").write(new_src)
    print("   OK views.py: webhook swapped to IntaSend (challenge-verified)")

s=open(SETTINGS,encoding="utf-8").read()
if "Agricore IntaSend webhook (idempotent)" in s:
    print("   settings.py challenge present, skip")
else:
    new=s.rstrip("\n")+"\n\n\n"+setblk.rstrip("\n")+"\n"; ast.parse(new)
    open(SETTINGS,"w",encoding="utf-8").write(new)
    print("   OK settings.py: INTASEND_WEBHOOK_CHALLENGE added")
PYEOF
rc=$?
set -e
if [ "$rc" -ne 0 ]; then
  echo ">> Failed (rc=$rc). Restoring."
  cp -a "$BK/utils/payments.py" "$PAY"; cp -a "$BK/utils/flutterwave.py" "$FW"
  cp -a "$BK/escrow/api/views.py" "$VIEWS"; cp -a "$BK/settings.py" "$SETTINGS"
  exit "$rc"
fi

if [ -f .env ]; then
  if grep -q "INTASEND_WEBHOOK_CHALLENGE" .env; then
    echo "   .env already has INTASEND_WEBHOOK_CHALLENGE, skip"
  else
    cat >> .env <<'ENVEOF'

# Set this to the SAME secret you enter as the webhook "challenge" in the IntaSend dashboard.
INTASEND_WEBHOOK_CHALLENGE=change_me_match_intasend_dashboard
ENVEOF
    echo "   OK .env: INTASEND_WEBHOOK_CHALLENGE placeholder appended"
  fi
fi

echo; echo "DONE"
echo ">> Restart the server. No migration needed."
echo ">> Rollback: cp -a $BK/utils/payments.py $PAY ; cp -a $BK/utils/flutterwave.py $FW ; cp -a $BK/escrow/api/views.py $VIEWS ; cp -a $BK/settings.py $SETTINGS"
